with scored as (select id, store_name, opened_date, sqft, sum(sqft) over (partition by city, region) as city_sum_sqft, last_value(region) ignore nulls over w_hist as last_known_region, lag(sqft, 1) over (order by sqft, id) as prev_sqft from stores where city in ('Singapore', 'New York', 'Bangkok') window w_hist as (partition by city order by opened_date, id rows between unbounded preceding and current row)) select case when sqft >= 14211 then 'LARGE' else 'SMALL' end as sqft_tier, count(*) as row_count, count(distinct id) as distinct_ids, count(*) as row_count_2 from scored group by 1 order by row_count_2 desc nulls first;
